import { useSeoMeta } from '@unhead/react';
import { Link } from 'react-router-dom';
import { useNostr } from '@nostrify/react';
import { useQuery } from '@tanstack/react-query';
import { useCurrentUser } from '@/hooks/useCurrentUser';
import { useIsAdmin } from '@/hooks/useIsAdmin';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { SocialShareButtons } from '@/components/SocialShareButtons';
import { ZapButton } from '@/components/ZapButton';
import { ShareDialog } from '@/components/share/ShareDialog';
import { MapPin, Calendar, ExternalLink, Globe, Share2 } from 'lucide-react';
import { format } from 'date-fns';
import { POPUP_TYPE_CONFIG, POPUP_STATUS_CONFIG, type PopUpType, type PopUpStatus, type PopUpEventData } from '@/lib/popupTypes';
import { WorldMap } from '@/components/popup/WorldMap';

export default function PopUp() {
  const { nostr } = useNostr();
  const { user } = useCurrentUser();
  const isAdmin = useIsAdmin();

  useSeoMeta({
    title: 'PopUp Events - BitPopArt | Art Exhibitions Worldwide',
    description: 'Discover BitPopArt exhibitions, pop-up shops, and events around the world. Join Johannes Oppewal\'s global art journey and find events near you.',
    keywords: 'bitpopart events, pop art exhibition, bitcoin art events, popup art show, art exhibitions worldwide, nostr events, bitcoin art popup, johannes oppewal events',
    author: 'Johannes Oppewal (BitPopArt)',
    ogType: 'website',
    ogTitle: 'PopUp Events - BitPopArt | Art Exhibitions Worldwide',
    ogDescription: 'Discover BitPopArt exhibitions, pop-up shops, and events around the world. Join Johannes Oppewal\'s global art journey.',
    ogImage: 'https://bitpopart.com/bitpopart-logo.png',
    ogImageAlt: 'BitPopArt PopUp Events',
    ogSiteName: 'BitPopArt',
    ogUrl: 'https://bitpopart.com/popup',
    twitterCard: 'summary_large_image',
    twitterTitle: 'PopUp Events - BitPopArt | Art Exhibitions Worldwide',
    twitterDescription: 'Discover BitPopArt exhibitions, pop-up shops, and events around the world.',
    twitterImage: 'https://bitpopart.com/bitpopart-logo.png',
    robots: 'index, follow, max-snippet:-1, max-image-preview:large',
  });

  // Fetch all PopUp events (kind 31922)
  const { data: popupEvents = [], isLoading } = useQuery({
    queryKey: ['popup-events-public', user?.pubkey],
    queryFn: async (c) => {
      const signal = AbortSignal.any([c.signal, AbortSignal.timeout(3000)]);
      
      // If user is logged in, show their events, otherwise show from specific authors
      const filters = user?.pubkey
        ? [{ kinds: [31922], authors: [user.pubkey], '#t': ['bitpopart-popup'], limit: 100 }]
        : [{ kinds: [31922], '#t': ['bitpopart-popup'], limit: 100 }];

      const events = await nostr.query(filters, { signal });
      
      // Parse events into PopUpEventData
      const parsedEvents: PopUpEventData[] = events
        .map((event): PopUpEventData | null => {
          const id = event.tags.find(t => t[0] === 'd')?.[1] || event.id;
          const title = event.tags.find(t => t[0] === 'title')?.[1] || 'Untitled';
          const location = event.tags.find(t => t[0] === 'location')?.[1] || '';
          const startDate = event.tags.find(t => t[0] === 'start')?.[1] || '';
          const endDate = event.tags.find(t => t[0] === 'end')?.[1];
          const image = event.tags.find(t => t[0] === 'image')?.[1];
          const galleryImages = event.tags.filter(t => t[0] === 'gallery').map(t => t[1]);
          const link = event.tags.find(t => t[0] === 'r')?.[1];
          const type = event.tags.find(t => t[0] === 't' && ['art', 'shop', 'event'].includes(t[1]))?.[1] as PopUpType || 'art';
          const status = event.tags.find(t => t[0] === 'status')?.[1] as PopUpStatus || 'confirmed';

          let description = '';
          let latitude = 0;
          let longitude = 0;

          try {
            const contentData = JSON.parse(event.content);
            description = contentData.description || '';
            latitude = contentData.coordinates?.lat || 0;
            longitude = contentData.coordinates?.lon || 0;
          } catch {
            description = event.content;
          }

          if (!latitude || !longitude) return null;

          return {
            id,
            title,
            description,
            type,
            status,
            location,
            latitude,
            longitude,
            startDate,
            endDate,
            image,
            galleryImages,
            link,
            event,
          };
        })
        .filter((e): e is PopUpEventData => e !== null)
        .sort((a, b) => b.startDate.localeCompare(a.startDate));

      return parsedEvents;
    },
  });

  // Separate active and past events
  const activeEvents = popupEvents
    .filter(e => {
      const isFinished = e.event.tags.find(t => t[0] === 'finished')?.[1] === 'true';
      return !isFinished;
    })
    .sort((a, b) => a.startDate.localeCompare(b.startDate)); // Sort soonest first

  const pastEvents = popupEvents
    .filter(e => {
      const isFinished = e.event.tags.find(t => t[0] === 'finished')?.[1] === 'true';
      return isFinished;
    })
    .sort((a, b) => b.startDate.localeCompare(a.startDate)); // Sort most recent first

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 via-pink-50 to-yellow-50 dark:from-gray-900 dark:via-orange-900/20 dark:to-yellow-900/20">
      <div className="container mx-auto px-4 py-12">
        {/* Header */}
        <div className="text-center mb-12">
          <div className="flex items-center justify-center mb-4 gap-3">
            <img 
              src={`${import.meta.env.BASE_URL || '/'}PopUP_button_1.svg`} 
              alt="PopUp" 
              className="h-12 w-12 flex-shrink-0" 
            />
            <h1 className="text-5xl font-bold leading-tight gradient-header-text">
              PopUp Events
            </h1>
          </div>
          <p className="text-xl text-gray-600 dark:text-gray-300 max-w-2xl mx-auto">
            Discover BitPopArt exhibitions, pop-up shops, and events happening around the world
          </p>
        </div>

        {/* World Map */}
        <Card className="mb-12 overflow-hidden">
          <CardHeader>
            <CardTitle className="flex items-center">
              <MapPin className="h-5 w-5 mr-2" />
              World Tour Map
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            {isLoading ? (
              <Skeleton className="h-[500px] w-full" />
            ) : popupEvents.length === 0 ? (
              <div className="h-[500px] flex items-center justify-center text-muted-foreground bg-gray-100 dark:bg-gray-800">
                <div className="text-center">
                  <Globe className="h-16 w-16 mx-auto mb-4 opacity-50" />
                  <p>No PopUp events scheduled yet</p>
                </div>
              </div>
            ) : (
              <div className="h-[500px] w-full">
                <WorldMap events={popupEvents} />
              </div>
            )}
          </CardContent>
        </Card>

        {/* Active Events Schedule */}
        <div className="space-y-6">
          <h2 className="text-3xl font-bold text-center mb-8">Event Schedule</h2>
          
          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {[...Array(6)].map((_, i) => (
                <Card key={i}>
                  <Skeleton className="h-48 w-full rounded-t-lg" />
                  <CardHeader className="space-y-2">
                    <Skeleton className="h-6 w-3/4" />
                    <Skeleton className="h-4 w-full" />
                    <Skeleton className="h-4 w-5/6" />
                  </CardHeader>
                </Card>
              ))}
            </div>
          ) : activeEvents.length === 0 && pastEvents.length === 0 ? (
            <Card className="max-w-md mx-auto">
              <CardContent className="py-12 text-center">
                <Globe className="h-16 w-16 mx-auto text-muted-foreground mb-4" />
                <h3 className="text-xl font-semibold mb-2">No Events Yet</h3>
                <p className="text-muted-foreground">
                  Check back soon for upcoming PopUp events!
                </p>
              </CardContent>
            </Card>
          ) : activeEvents.length === 0 ? (
            <Card className="max-w-md mx-auto">
              <CardContent className="py-12 text-center">
                <Globe className="h-16 w-16 mx-auto text-muted-foreground mb-4" />
                <h3 className="text-xl font-semibold mb-2">No Active Events</h3>
                <p className="text-muted-foreground">
                  All events are finished. Check out past events below!
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {activeEvents.map((event) => {
                const typeConfig = POPUP_TYPE_CONFIG[event.type];
                const statusConfig = POPUP_STATUS_CONFIG[event.status];

                return (
                  <Link key={event.id} to={`/popup/${event.id}`}>
                    <Card className="h-full hover:shadow-xl transition-all duration-300 overflow-hidden group bg-white dark:bg-gray-800">
                    {event.image ? (
                      <div className="relative h-56 overflow-hidden">
                        <img
                          src={event.image}
                          alt={event.title}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent" />
                        <div className="absolute top-3 left-3 flex gap-2">
                          <Badge className={`${typeConfig.bgColor} ${typeConfig.color} border shadow-lg`}>
                            {typeConfig.icon} {typeConfig.label}
                          </Badge>
                          {event.status === 'option' && (
                            <Badge className={`${statusConfig.bgColor} ${statusConfig.color} border shadow-lg`}>
                              {statusConfig.label}
                            </Badge>
                          )}
                        </div>
                        {/* Zap button */}
                        {event.event && (
                          <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                            <ZapButton
                              authorPubkey={event.event.pubkey}
                              event={event.event}
                              eventTitle={event.title}
                              size="sm"
                              variant="default"
                              className="bg-orange-600 hover:bg-orange-700 text-white border-0 shadow-lg h-8 w-8 p-0"
                              showLabel={false}
                            />
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="relative h-56 bg-gradient-to-br from-orange-100 via-pink-100 to-yellow-100 dark:from-orange-900/20 dark:via-pink-900/20 dark:to-yellow-900/20 flex items-center justify-center">
                        <div className="text-center">
                          <span className="text-6xl opacity-40">{typeConfig.icon}</span>
                        </div>
                        <div className="absolute top-3 right-3 flex gap-2">
                          <Badge className={`${typeConfig.bgColor} ${typeConfig.color} border`}>
                            {typeConfig.label}
                          </Badge>
                          {event.status === 'option' && (
                            <Badge className={`${statusConfig.bgColor} ${statusConfig.color} border`}>
                              {statusConfig.label}
                            </Badge>
                          )}
                        </div>
                      </div>
                    )}
                    <CardHeader className="space-y-3">
                      <h3 className="text-2xl font-bold group-hover:text-orange-600 transition-colors line-clamp-2">
                        {event.title}
                      </h3>
                      {event.description && (
                        <p className="text-muted-foreground line-clamp-3 text-sm">
                          {event.description}
                        </p>
                      )}
                      <div className="space-y-2 text-sm text-muted-foreground">
                        <div className="flex items-center gap-2">
                          <MapPin className="h-4 w-4 flex-shrink-0" />
                          <span className="line-clamp-1 font-medium">{event.location}</span>
                        </div>
                        <div className="flex items-center gap-2">
                          <Calendar className="h-4 w-4 flex-shrink-0" />
                          <span className="font-medium">
                            {format(new Date(event.startDate), 'MMM d, yyyy')}
                            {event.endDate && ` - ${format(new Date(event.endDate), 'MMM d, yyyy')}`}
                          </span>
                        </div>
                      </div>
                      {event.link && (
                        <a
                          href={event.link}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center text-orange-600 hover:text-orange-700 transition-colors pt-2 font-medium"
                        >
                          <span className="text-sm">Learn more</span>
                          <ExternalLink className="h-4 w-4 ml-2" />
                        </a>
                      )}

                      {/* Share Button */}
                      {event.event && (
                        <div className="pt-3">
                          <ShareDialog
                            title={event.title}
                            description={event.description}
                            url={`${window.location.origin}/popup#${event.id}`}
                            imageUrl={event.image}
                            category={event.type}
                            contentType="event"
                            eventRef={{
                              id: event.event.id,
                              kind: event.event.kind,
                              pubkey: event.event.pubkey,
                              dTag: event.id
                            }}
                          >
                            <Button
                              variant="outline"
                              size="sm"
                              className="w-full"
                            >
                              <Share2 className="h-4 w-4 mr-2" />
                              Share Event
                            </Button>
                          </ShareDialog>
                        </div>
                      )}

                      {/* Admin Share Buttons */}
                      {isAdmin && event.event && (
                        <SocialShareButtons
                          event={event.event}
                          url={`/popup#${event.id}`}
                          title={event.title}
                          description={event.description}
                          image={event.image}
                          contentType="popup"
                          className="pt-2"
                        />
                      )}
                    </CardHeader>
                  </Card>
                  </Link>
                );
              })}
            </div>
          )}
        </div>

        {/* Past Events Section */}
        {pastEvents.length > 0 && (
          <div className="space-y-6 mt-16">
            <h2 className="text-3xl font-bold text-center mb-8">Past Events</h2>
            
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-4">
              {pastEvents.map((event) => {
                const typeConfig = POPUP_TYPE_CONFIG[event.type];
                const statusConfig = POPUP_STATUS_CONFIG[event.status];

                return (
                  <Link key={event.id} to={`/popup/${event.id}`}>
                    <Card className="hover:shadow-lg transition-all duration-300 overflow-hidden group bg-white dark:bg-gray-800 opacity-75 h-full">
                    {event.image ? (
                      <div className="relative h-32 overflow-hidden">
                        <img
                          src={event.image}
                          alt={event.title}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent" />
                        <div className="absolute top-2 left-2">
                          <Badge className={`${typeConfig.bgColor} ${typeConfig.color} border shadow-lg text-xs`}>
                            {typeConfig.icon}
                          </Badge>
                        </div>
                        {/* Share button overlay */}
                        {event.event && (
                          <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200" onClick={(e) => e.stopPropagation()}>
                            <ShareDialog
                              title={event.title}
                              description={event.description}
                              url={`${window.location.origin}/popup#${event.id}`}
                              imageUrl={event.image}
                              category={event.type}
                              contentType="event"
                              eventRef={{
                                id: event.event.id,
                                kind: event.event.kind,
                                pubkey: event.event.pubkey,
                                dTag: event.id
                              }}
                            >
                              <Button
                                variant="default"
                                size="sm"
                                className="bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 border-0 shadow-lg h-7 w-7 p-0"
                              >
                                <Share2 className="h-3 w-3" />
                              </Button>
                            </ShareDialog>
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="relative h-32 bg-gradient-to-br from-purple-100 via-pink-100 to-indigo-100 dark:from-purple-900/20 dark:via-pink-900/20 dark:to-indigo-900/20 flex items-center justify-center">
                        <span className="text-4xl opacity-40">{typeConfig.icon}</span>
                      </div>
                    )}
                    <CardContent className="p-3">
                      <h3 className="font-semibold text-sm line-clamp-2 mb-1">
                        {event.title}
                      </h3>
                      <div className="space-y-1 text-xs text-muted-foreground">
                        <div className="flex items-center gap-1">
                          <MapPin className="h-3 w-3 flex-shrink-0" />
                          <span className="line-clamp-1">{event.location}</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Calendar className="h-3 w-3 flex-shrink-0" />
                          <span className="line-clamp-1">
                            {format(new Date(event.startDate), 'MMM d, yyyy')}
                          </span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                  </Link>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
