import { useMemo, useState, useRef } from 'react';
import { useNostr } from '@nostrify/react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCurrentUser } from '@/hooks/useCurrentUser';
import { useNostrPublish } from '@/hooks/useNostrPublish';
import { useUploadFile } from '@/hooks/useUploadFile';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Checkbox } from '@/components/ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import {
  MapPin,
  Plus,
  Calendar,
  Loader2,
  Trash2,
  Edit,
  X,
  Upload,
  CheckCircle2,
  Globe,
  FileText,
  Link as LinkIcon
} from 'lucide-react';
import { format } from 'date-fns';
import type { NostrEvent } from '@nostrify/nostrify';
import { POPUP_TYPE_CONFIG, POPUP_STATUS_CONFIG, coordinatesToGeohash, generateUUID, type PopUpType, type PopUpStatus } from '@/lib/popupTypes';

interface PopUpFormData {
  title: string;
  description: string;
  type: PopUpType;
  status: PopUpStatus;
  location: string;
  latitude: string;
  longitude: string;
  startDate: string;
  endDate: string;
  image: string;
  galleryImages: string[];
  link: string;
  brandSite: string;
  finished: boolean;
}

type BrandSiteInputMode = 'url' | 'html' | 'pdf';

export function PopUpManagement() {
  const { nostr } = useNostr();
  const { user } = useCurrentUser();
  const { mutate: createEvent } = useNostrPublish();
  const { mutateAsync: uploadFile } = useUploadFile();
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isCreating, setIsCreating] = useState(false);
  const [editingEvent, setEditingEvent] = useState<NostrEvent | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadingGallery, setUploadingGallery] = useState(false);
  const [brandSiteMode, setBrandSiteMode] = useState<BrandSiteInputMode>('url');
  const [brandSiteHtml, setBrandSiteHtml] = useState('');
  const galleryFileInputRef = useRef<HTMLInputElement>(null);
  const brandSitePdfInputRef = useRef<HTMLInputElement>(null);
  const [formData, setFormData] = useState<PopUpFormData>({
    title: '',
    description: '',
    type: 'art',
    status: 'confirmed',
    location: '',
    latitude: '',
    longitude: '',
    startDate: '',
    endDate: '',
    image: '',
    galleryImages: [],
    link: '',
    brandSite: '',
    finished: false,
  });

  // Fetch user's PopUp events (kind 31922)
  const { data: popupEvents = [], isLoading } = useQuery({
    queryKey: ['popup-events', user?.pubkey],
    queryFn: async (c) => {
      if (!user?.pubkey) return [];
      const signal = AbortSignal.any([c.signal, AbortSignal.timeout(3000)]);
      const events = await nostr.query(
        [{ kinds: [31922], authors: [user.pubkey], '#t': ['bitpopart-popup'], limit: 100 }],
        { signal }
      );
      // Separate and sort: active events (soonest first), then past events (most recent first)
      const active: NostrEvent[] = [];
      const past: NostrEvent[] = [];
      
      events.forEach(event => {
        const isFinished = event.tags.find(t => t[0] === 'finished')?.[1] === 'true';
        if (isFinished) {
          past.push(event);
        } else {
          active.push(event);
        }
      });

      // Sort active events: soonest first
      active.sort((a, b) => {
        const aStart = a.tags.find(t => t[0] === 'start')?.[1] || '';
        const bStart = b.tags.find(t => t[0] === 'start')?.[1] || '';
        return aStart.localeCompare(bStart);
      });

      // Sort past events: most recent first
      past.sort((a, b) => {
        const aStart = a.tags.find(t => t[0] === 'start')?.[1] || '';
        const bStart = b.tags.find(t => t[0] === 'start')?.[1] || '';
        return bStart.localeCompare(aStart);
      });

      return [...active, ...past];
    },
    enabled: !!user?.pubkey,
  });

  const handleInputChange = (field: keyof PopUpFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Check file size (10MB limit)
    const maxSize = 10 * 1024 * 1024;
    if (file.size > maxSize) {
      toast.error('File is larger than 10MB. Please choose a smaller file.');
      return;
    }

    setIsUploading(true);
    try {
      const tags = await uploadFile(file);
      const imageUrl = tags[0][1]; // Get URL from first tag
      setFormData(prev => ({ ...prev, image: imageUrl }));
      toast.success('Image uploaded successfully!');
    } catch (error) {
      console.error('Upload error:', error);
      toast.error('Failed to upload image');
    } finally {
      setIsUploading(false);
    }
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, image: '' }));
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleBrandSiteFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const isPdf = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
    const isHtml = file.type === 'text/html' || /\.(html?|xhtml)$/i.test(file.name);

    if (!isPdf && !isHtml) {
      toast.error('Please upload a PDF or HTML file.');
      return;
    }

    if (file.size > 15 * 1024 * 1024) {
      toast.error('File is larger than 15MB. Please choose a smaller file.');
      return;
    }

    try {
      if (isHtml) {
        const html = await file.text();
        const dataUrl = `data:text/html;charset=utf-8,${encodeURIComponent(html)}`;
        setFormData(prev => ({ ...prev, brandSite: dataUrl }));
        setBrandSiteMode('url');
        toast.warning(
          'HTML file loaded for local preview only. Note: this cannot be saved to Nostr — only https:// URLs can be stored. To share this page, host it online and paste the URL instead.',
          { duration: 10000 }
        );
        return;
      }

      const tags = await uploadFile(file);
      const url = tags[0]?.[1];
      if (url) {
        setFormData(prev => ({ ...prev, brandSite: url }));
        setBrandSiteMode('url');
        toast.success('PDF uploaded and linked to Event Brand Website.');
      }
    } catch (error) {
      console.error('Brand site file upload error:', error);
      toast.error('Failed to upload file');
    } finally {
      if (brandSitePdfInputRef.current) {
        brandSitePdfInputRef.current.value = '';
      }
    }
  };

  const applyBrandSiteHtml = () => {
    if (!brandSiteHtml.trim()) {
      toast.error('Paste your HTML code first.');
      return;
    }

    const htmlBlob = new Blob([brandSiteHtml], { type: 'text/html' });
    const url = URL.createObjectURL(htmlBlob);
    setFormData(prev => ({ ...prev, brandSite: url }));
    setBrandSiteMode('url');
    toast.warning(
      'HTML preview created locally. Note: this cannot be saved to Nostr — only https:// URLs can be stored. To share this page, host it online and paste the URL instead.',
      { duration: 10000 }
    );
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validation
    if (!formData.title.trim()) {
      toast.error('Please enter a title');
      return;
    }
    if (!formData.location.trim()) {
      toast.error('Please enter a location');
      return;
    }
    if (!formData.latitude || !formData.longitude) {
      toast.error('Please enter coordinates');
      return;
    }
    if (!formData.startDate) {
      toast.error('Please enter a start date');
      return;
    }

    const lat = parseFloat(formData.latitude);
    const lon = parseFloat(formData.longitude);

    if (isNaN(lat) || lat < -90 || lat > 90) {
      toast.error('Latitude must be between -90 and 90');
      return;
    }
    if (isNaN(lon) || lon < -180 || lon > 180) {
      toast.error('Longitude must be between -180 and 180');
      return;
    }

    const eventId = editingEvent?.tags.find(t => t[0] === 'd')?.[1] || generateUUID();
    const geohash = coordinatesToGeohash(lat, lon);

    const tags: string[][] = [
      ['d', eventId],
      ['title', formData.title],
      ['start', formData.startDate],
      ['location', formData.location],
      ['g', geohash],
      ['t', 'bitpopart-popup'],
      ['t', formData.type],
      ['status', formData.status],
    ];

    if (formData.endDate) {
      tags.push(['end', formData.endDate]);
    }
    if (formData.image) {
      tags.push(['image', formData.image]);
    }
    // Add gallery images
    formData.galleryImages.forEach(imgUrl => {
      tags.push(['gallery', imgUrl]);
    });
    if (formData.link) {
      tags.push(['r', formData.link]);
    }
    if (formData.brandSite) {
      const isBlob = formData.brandSite.startsWith('blob:');
      const isDataUrl = formData.brandSite.startsWith('data:');
      if (isBlob || isDataUrl) {
        // blob: and data: URLs are local/temporary and cannot be stored on Nostr.
        // They also cause Alby's signing popup to go blank when trying to render the tag.
        // Warn the user and skip this tag.
        toast.warning(
          'The Event Brand Website could not be saved: blob/data URLs are not supported on Nostr. Please enter a real https:// URL instead.',
          { duration: 8000 }
        );
      } else {
        tags.push(['brand-site', formData.brandSite]);
      }
    }
    // Store coordinates in content as JSON for easy retrieval
    const contentData = {
      description: formData.description,
      coordinates: { lat, lon },
    };

    // If marked as finished, do not publish to Nostr.
    // If editing an existing published event, send a deletion event to remove it from relays.
    if (formData.finished) {
      if (editingEvent) {
        const existingEventId = editingEvent.tags.find(t => t[0] === 'd')?.[1];
        if (existingEventId) {
          createEvent(
            {
              kind: 5,
              content: 'Event marked as finished',
              tags: [['a', `31922:${editingEvent.pubkey}:${existingEventId}`]],
            },
            {
              onSuccess: () => {
                toast.success('Event marked as finished and removed from Nostr.');
                queryClient.invalidateQueries({ queryKey: ['popup-events'] });
              },
              onError: () => {
                toast.info('Event marked as finished (could not remove from Nostr).');
              },
            }
          );
        } else {
          toast.info('Event marked as finished and will not be published to Nostr.');
        }
      } else {
        toast.info('Event marked as finished and will not be published to Nostr.');
      }
      setIsCreating(false);
      setEditingEvent(null);
      setFormData({
        title: '',
        description: '',
        type: 'art',
        status: 'confirmed',
        location: '',
        latitude: '',
        longitude: '',
        startDate: '',
        endDate: '',
        image: '',
        galleryImages: [],
        link: '',
        brandSite: '',
        finished: false,
      });
      return;
    }

    createEvent(
      {
        kind: 31922,
        content: JSON.stringify(contentData),
        tags,
      },
      {
        onSuccess: () => {
          toast.success(editingEvent ? 'PopUp event updated!' : 'PopUp event created!');
          setIsCreating(false);
          setEditingEvent(null);
          setFormData({
            title: '',
            description: '',
            type: 'art',
            status: 'confirmed',
            location: '',
            latitude: '',
            longitude: '',
            startDate: '',
            endDate: '',
            image: '',
            galleryImages: [],
            link: '',
            brandSite: '',
            finished: false,
          });
          queryClient.invalidateQueries({ queryKey: ['popup-events'] });
        },
        onError: (error) => {
          console.error('Publish error:', error);
          toast.error('Failed to save PopUp event');
        },
      }
    );
  };

  const handleEdit = (event: NostrEvent) => {
    const title = event.tags.find(t => t[0] === 'title')?.[1] || '';
    const location = event.tags.find(t => t[0] === 'location')?.[1] || '';
    const startDate = event.tags.find(t => t[0] === 'start')?.[1] || '';
    const endDate = event.tags.find(t => t[0] === 'end')?.[1] || '';
    const image = event.tags.find(t => t[0] === 'image')?.[1] || '';
    const galleryImages = event.tags.filter(t => t[0] === 'gallery').map(t => t[1]);
    const link = event.tags.find(t => t[0] === 'r')?.[1] || '';
    const brandSite = event.tags.find(t => t[0] === 'brand-site')?.[1] || event.tags.find(t => t[0] === 'website')?.[1] || '';
    const type = event.tags.find(t => t[0] === 't' && ['art', 'shop', 'event'].includes(t[1]))?.[1] as PopUpType || 'art';
    const status = event.tags.find(t => t[0] === 'status')?.[1] as PopUpStatus || 'confirmed';
    const finished = event.tags.find(t => t[0] === 'finished')?.[1] === 'true';

    let description = '';
    let lat = '';
    let lon = '';

    try {
      const contentData = JSON.parse(event.content);
      description = contentData.description || '';
      lat = contentData.coordinates?.lat?.toString() || '';
      lon = contentData.coordinates?.lon?.toString() || '';
    } catch {
      description = event.content;
    }

    setFormData({
      title,
      description,
      type,
      status,
      location,
      latitude: lat,
      longitude: lon,
      startDate,
      endDate,
      image,
      galleryImages,
      link,
      brandSite,
      finished,
    });
    setEditingEvent(event);
    setIsCreating(true);
  };

  const handleDelete = (event: NostrEvent) => {
    const eventId = event.tags.find(t => t[0] === 'd')?.[1];
    if (!eventId) return;

    if (confirm('Are you sure you want to delete this PopUp event?')) {
      createEvent(
        {
          kind: 5,
          content: 'Deleted PopUp event',
          tags: [['a', `31922:${event.pubkey}:${eventId}`]],
        },
        {
          onSuccess: () => {
            toast.success('PopUp event deleted');
            queryClient.invalidateQueries({ queryKey: ['popup-events'] });
          },
        }
      );
    }
  };

  const handleCancel = () => {
    setIsCreating(false);
    setEditingEvent(null);
    setFormData({
      title: '',
      description: '',
      type: 'art',
      status: 'confirmed',
      location: '',
      latitude: '',
      longitude: '',
      startDate: '',
      endDate: '',
      image: '',
      galleryImages: [],
      link: '',
      finished: false,
    });
  };

  const handleGalleryUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadingGallery(true);
    try {
      const tags = await uploadFile(file);
      const imageUrl = tags[0]?.[1];
      
      if (imageUrl) {
        setFormData(prev => ({ 
          ...prev, 
          galleryImages: [...prev.galleryImages, imageUrl] 
        }));
        toast.success('Gallery image uploaded!');
      }
    } catch (error) {
      console.error('Gallery upload error:', error);
      toast.error('Failed to upload gallery image');
    } finally {
      setUploadingGallery(false);
      if (galleryFileInputRef.current) {
        galleryFileInputRef.current.value = '';
      }
    }
  };

  const removeGalleryImage = (index: number) => {
    setFormData(prev => ({
      ...prev,
      galleryImages: prev.galleryImages.filter((_, i) => i !== index)
    }));
  };

  return (
    <div className="space-y-6">
      {/* Create/Edit Form */}
      {isCreating ? (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <span className="flex items-center">
                <Plus className="h-5 w-5 mr-2" />
                {editingEvent ? 'Edit PopUp Event' : 'Create PopUp Event'}
              </span>
              <Button variant="ghost" size="sm" onClick={handleCancel}>
                <X className="h-4 w-4" />
              </Button>
            </CardTitle>
            <CardDescription>
              Add a new PopUp event location to appear on the world map
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="title">Event Title *</Label>
                <Input
                  id="title"
                  placeholder="BitPopArt Exhibition Amsterdam"
                  value={formData.title}
                  onChange={(e) => handleInputChange('title', e.target.value)}
                  required
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="type">Event Type *</Label>
                  <Select
                    value={formData.type}
                    onValueChange={(value) => handleInputChange('type', value)}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {Object.entries(POPUP_TYPE_CONFIG).map(([key, config]) => (
                        <SelectItem key={key} value={key}>
                          {config.icon} {config.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="status">Event Status *</Label>
                  <Select
                    value={formData.status}
                    onValueChange={(value) => handleInputChange('status', value)}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {Object.entries(POPUP_STATUS_CONFIG).map(([key, config]) => (
                        <SelectItem key={key} value={key}>
                          {config.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  placeholder="Join us for an exciting pop-up exhibition..."
                  value={formData.description}
                  onChange={(e) => handleInputChange('description', e.target.value)}
                  rows={3}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="location">Location *</Label>
                <Input
                  id="location"
                  placeholder="Amsterdam, Netherlands"
                  value={formData.location}
                  onChange={(e) => handleInputChange('location', e.target.value)}
                  required
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="latitude">Latitude * (-90 to 90)</Label>
                  <Input
                    id="latitude"
                    type="number"
                    step="any"
                    placeholder="52.3676"
                    value={formData.latitude}
                    onChange={(e) => handleInputChange('latitude', e.target.value)}
                    required
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="longitude">Longitude * (-180 to 180)</Label>
                  <Input
                    id="longitude"
                    type="number"
                    step="any"
                    placeholder="4.9041"
                    value={formData.longitude}
                    onChange={(e) => handleInputChange('longitude', e.target.value)}
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="startDate">Start Date *</Label>
                  <Input
                    id="startDate"
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => handleInputChange('startDate', e.target.value)}
                    required
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="endDate">End Date (optional)</Label>
                  <Input
                    id="endDate"
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => handleInputChange('endDate', e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="image">Event Image</Label>
                
                {formData.image ? (
                  <div className="space-y-2">
                    <div className="relative rounded-lg overflow-hidden border-2 border-gray-200 dark:border-gray-700">
                      <img
                        src={formData.image}
                        alt="Event preview"
                        className="w-full h-48 object-cover"
                      />
                      <Button
                        type="button"
                        variant="destructive"
                        size="sm"
                        className="absolute top-2 right-2"
                        onClick={handleRemoveImage}
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>
                    <Input
                      type="url"
                      placeholder="Or paste image URL"
                      value={formData.image}
                      onChange={(e) => handleInputChange('image', e.target.value)}
                    />
                  </div>
                ) : (
                  <div className="space-y-2">
                    <input
                      ref={fileInputRef}
                      id="image-upload"
                      type="file"
                      accept="image/*"
                      className="hidden"
                      onChange={handleImageUpload}
                      disabled={isUploading}
                    />
                    <Button
                      type="button"
                      variant="outline"
                      className="w-full"
                      onClick={() => fileInputRef.current?.click()}
                      disabled={isUploading}
                    >
                      {isUploading ? (
                        <>
                          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                          Uploading...
                        </>
                      ) : (
                        <>
                          <Upload className="h-4 w-4 mr-2" />
                          Upload Image
                        </>
                      )}
                    </Button>
                    <Input
                      type="url"
                      placeholder="Or paste image URL"
                      value={formData.image}
                      onChange={(e) => handleInputChange('image', e.target.value)}
                    />
                  </div>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="link">Event Link (optional)</Label>
                <Input
                  id="link"
                  type="url"
                  placeholder="https://example.com/event"
                  value={formData.link}
                  onChange={(e) => handleInputChange('link', e.target.value)}
                />
              </div>

              <div className="space-y-3">
                <div className="flex items-center justify-between gap-3">
                  <Label htmlFor="brandSite">Event Brand Website (optional)</Label>
                  <div className="flex items-center gap-2 rounded-md border p-1">
                    <Button type="button" size="sm" variant={brandSiteMode === 'url' ? 'default' : 'ghost'} onClick={() => setBrandSiteMode('url')}>
                      URL
                    </Button>
                    <Button type="button" size="sm" variant={brandSiteMode === 'html' ? 'default' : 'ghost'} onClick={() => setBrandSiteMode('html')}>
                      HTML
                    </Button>
                    <Button type="button" size="sm" variant={brandSiteMode === 'pdf' ? 'default' : 'ghost'} onClick={() => setBrandSiteMode('pdf')}>
                      PDF
                    </Button>
                  </div>
                </div>

                {brandSiteMode === 'url' && (
                  <Input
                    id="brandSite"
                    type="url"
                    placeholder="https://example.com/project-site-or-brochure.pdf"
                    value={formData.brandSite}
                    onChange={(e) => handleInputChange('brandSite', e.target.value)}
                  />
                )}

                {brandSiteMode === 'html' && (
                  <div className="space-y-2">
                    <Textarea
                      value={brandSiteHtml}
                      onChange={(e) => setBrandSiteHtml(e.target.value)}
                      rows={10}
                      placeholder="Paste full HTML code here (it will be converted into a page URL)."
                    />
                    <div className="flex flex-wrap gap-2">
                      <Button type="button" variant="outline" onClick={applyBrandSiteHtml}>
                        <FileText className="h-4 w-4 mr-2" />
                        Create page from HTML
                      </Button>
                      <Button type="button" variant="ghost" onClick={() => setBrandSiteHtml('')}>
                        Clear HTML
                      </Button>
                    </div>
                  </div>
                )}

                {brandSiteMode === 'pdf' && (
                  <div className="space-y-2">
                    <input
                      ref={brandSitePdfInputRef}
                      type="file"
                      accept="application/pdf,text/html,.html,.htm,.xhtml"
                      className="hidden"
                      onChange={handleBrandSiteFileUpload}
                    />
                    <Button type="button" variant="outline" onClick={() => brandSitePdfInputRef.current?.click()}>
                      <Upload className="h-4 w-4 mr-2" />
                      Upload PDF / HTML file
                    </Button>
                    <p className="text-xs text-muted-foreground">
                      The uploaded PDF or HTML file will be hosted and linked here automatically.
                    </p>
                  </div>
                )}

                <p className="text-xs text-muted-foreground">
                  Add a URL, upload a PDF, or create a page from full HTML code. It opens inside the BitPopArt site.
                </p>
              </div>

              <Separator />

              {/* Gallery Images */}
              <div className="space-y-2">
                <Label>Gallery Images (optional)</Label>
                <p className="text-sm text-muted-foreground">Add additional photos to create a gallery for this event</p>
                
                {formData.galleryImages.length > 0 && (
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-3">
                    {formData.galleryImages.map((imgUrl, index) => (
                      <div key={index} className="relative rounded-lg overflow-hidden border-2 border-gray-200 dark:border-gray-700">
                        <img
                          src={imgUrl}
                          alt={`Gallery ${index + 1}`}
                          className="w-full h-32 object-cover"
                        />
                        <Button
                          type="button"
                          variant="destructive"
                          size="sm"
                          className="absolute top-1 right-1 h-6 w-6 p-0"
                          onClick={() => removeGalleryImage(index)}
                        >
                          <X className="h-3 w-3" />
                        </Button>
                      </div>
                    ))}
                  </div>
                )}

                <input
                  ref={galleryFileInputRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={handleGalleryUpload}
                  disabled={uploadingGallery}
                />
                <Button
                  type="button"
                  variant="outline"
                  className="w-full"
                  onClick={() => galleryFileInputRef.current?.click()}
                  disabled={uploadingGallery}
                >
                  {uploadingGallery ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Uploading...
                    </>
                  ) : (
                    <>
                      <Upload className="h-4 w-4 mr-2" />
                      Add Gallery Image
                    </>
                  )}
                </Button>
              </div>

              <Separator />

              {/* Finished Checkbox */}
              <div className="space-y-2 p-4 border rounded-lg bg-gray-50 dark:bg-gray-900/20">
                <div className="flex items-center space-x-2">
                  <Checkbox
                    id="finished"
                    checked={formData.finished}
                    onCheckedChange={(checked) => setFormData(prev => ({ ...prev, finished: checked === true }))}
                  />
                  <Label htmlFor="finished" className="text-base font-medium flex items-center gap-2 cursor-pointer">
                    <CheckCircle2 className="h-4 w-4" />
                    Mark as Finished (Past Event)
                  </Label>
                </div>
                <p className="text-sm text-muted-foreground">
                  Check this box for completed events. They will appear in the "Past Events" section with smaller thumbnails.
                  {formData.finished ? ' (Event is marked as finished)' : ' (Event is active)'}
                </p>
              </div>

              <div className="flex gap-2">
                <Button type="submit" className="flex-1">
                  <Plus className="h-4 w-4 mr-2" />
                  {editingEvent ? 'Update Event' : 'Create Event'}
                </Button>
                <Button type="button" variant="outline" onClick={handleCancel}>
                  Cancel
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      ) : (
        <div className="text-center py-6">
          <Button onClick={() => setIsCreating(true)} size="lg">
            <Plus className="h-5 w-5 mr-2" />
            Add PopUp Event
          </Button>
        </div>
      )}

      <Separator />

      {/* Event List */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center">
            <MapPin className="h-5 w-5 mr-2" />
            Your PopUp Events
          </CardTitle>
          <CardDescription>
            Manage your worldwide PopUp schedule
          </CardDescription>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : popupEvents.length === 0 ? (
            <div className="text-center py-12">
              <MapPin className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <p className="text-muted-foreground">No PopUp events yet. Create your first one above!</p>
            </div>
          ) : (
            <div className="space-y-4">
              {popupEvents.map((event) => {
                const title = event.tags.find(t => t[0] === 'title')?.[1] || 'Untitled';
                const location = event.tags.find(t => t[0] === 'location')?.[1] || '';
                const startDate = event.tags.find(t => t[0] === 'start')?.[1] || '';
                const endDate = event.tags.find(t => t[0] === 'end')?.[1];
                const image = event.tags.find(t => t[0] === 'image')?.[1];
                const type = event.tags.find(t => t[0] === 't' && ['art', 'shop', 'event'].includes(t[1]))?.[1] as PopUpType || 'art';
                const status = event.tags.find(t => t[0] === 'status')?.[1] as PopUpStatus || 'confirmed';
                const finished = event.tags.find(t => t[0] === 'finished')?.[1] === 'true';
                const typeConfig = POPUP_TYPE_CONFIG[type];
                const statusConfig = POPUP_STATUS_CONFIG[status];

                return (
                  <Card key={event.id} className="overflow-hidden">
                    <div className="flex gap-4">
                      {image && (
                        <div className="w-32 h-24 flex-shrink-0">
                          <img
                            src={image}
                            alt={title}
                            className="w-full h-full object-cover"
                          />
                        </div>
                      )}
                      <div className="flex-1 p-4">
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-2 flex-wrap">
                              <h3 className="font-semibold text-lg">{title}</h3>
                              <Badge className={`${typeConfig.bgColor} ${typeConfig.color} border`}>
                                {typeConfig.icon} {typeConfig.label}
                              </Badge>
                              {status === 'option' && (
                                <Badge className={`${statusConfig.bgColor} ${statusConfig.color} border`}>
                                  {statusConfig.label}
                                </Badge>
                              )}
                              {finished && (
                                <Badge className="bg-gray-500 text-white border">
                                  <CheckCircle2 className="h-3 w-3 mr-1" />
                                  Finished
                                </Badge>
                              )}
                            </div>
                            <div className="flex flex-wrap gap-3 text-sm text-muted-foreground">
                              <span className="flex items-center gap-1">
                                <MapPin className="h-3 w-3" />
                                {location}
                              </span>
                              <span className="flex items-center gap-1">
                                <Calendar className="h-3 w-3" />
                                {format(new Date(startDate), 'MMM d, yyyy')}
                                {endDate && ` - ${format(new Date(endDate), 'MMM d, yyyy')}`}
                              </span>
                            </div>
                          </div>
                          <div className="flex gap-2">
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleEdit(event)}
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleDelete(event)}
                            >
                              <Trash2 className="h-4 w-4 text-red-500" />
                            </Button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </Card>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
