import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { createHead, UnheadProvider } from '@unhead/react/client';
import { InferSeoMetaPlugin } from '@unhead/addons';
import { Suspense } from 'react';
import NostrProvider from '@/components/NostrProvider';
import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { NostrLoginProvider } from '@nostrify/react/login';
import { AppProvider } from '@/components/AppProvider';
import { ThemeColorLoader } from '@/components/ThemeColorLoader';
import { AppConfig } from '@/contexts/AppContext';
import AppRouter from './AppRouter';

const head = createHead({
  plugins: [
    InferSeoMetaPlugin(),
  ],
});

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false, // Don't re-fetch on tab focus — causes blank flicker
      staleTime: 30000,            // 30 s default; individual hooks can override this
      gcTime: 300000,              // Keep unused cache for 5 min to avoid blank states
      retry: 2,                    // Retry twice on network failure before giving up
      retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 8000),
    },
  },
});

const defaultConfig: AppConfig = {
  theme: "light",
  relayUrl: "wss://relay.ditto.pub",
  imageProxy: "https://wsrv.nl",
};

const presetRelays = [
  // read+write: queried for content AND published to.
  { url: 'wss://relay.ditto.pub', name: 'Ditto', read: true, write: true },
  { url: 'wss://relay.dreamith.to', name: 'Dreamith', read: true, write: true },
  // write-only: published to for wide distribution, but NOT queried for reads
  // so a slow relay can't gate every query. (Ditto uses this same pattern.)
  { url: 'wss://relay.primal.net', name: 'Primal', read: false, write: true },
  // Gamestr gaming relay — write game scores (kind 30762) here for discovery on gamestr.io
  { url: 'wss://main.relay.gamestr.io', name: 'Gamestr', read: false, write: true },
];

export function App() {
  return (
    <UnheadProvider head={head}>
      <AppProvider storageKey="nostr:app-config" defaultConfig={defaultConfig} presetRelays={presetRelays}>
        <QueryClientProvider client={queryClient}>
          <NostrLoginProvider storageKey='nostr:login'>
            <NostrProvider>
              <ThemeColorLoader />
              <TooltipProvider>
                <Toaster />
                <Sonner />
                <Suspense>
                  <AppRouter />
                </Suspense>
              </TooltipProvider>
            </NostrProvider>
          </NostrLoginProvider>
        </QueryClientProvider>
      </AppProvider>
    </UnheadProvider>
  );
}

export default App;
