          <div className="w-full h-full bg-gradient-to-br from-orange-100 to-pink-100 dark:from-orange-900/20 dark:to-pink-900/20 flex items-center justify-center">
            <ShoppingCart className="h-10 w-10 text-orange-300" />
          </div>
