/** Default icons per variant when no explicit icon is set */
function getDefaultIcon(variant: HomepageButton['variant']): React.ComponentType<{ className?: string }> | null {
  if (variant === 'primary') return Sparkles;
  if (variant === 'accent') return MapPin;
  return Gift;
}

function DynamicButton({
  btn,
  size = 'default',
  mobileIconOnly = false,
  mobileShowLabel = false,
}: {
  btn: HomepageButton;
  size?: 'default' | 'lg' | 'sm';
  /** Hide label on mobile, icon-only square button */
  mobileIconOnly?: boolean;
  /** Keep label visible on mobile even when mobileIconOnly is set (for important buttons like Nostr) */
  mobileShowLabel?: boolean;
}) {
  const isExternal = btn.url.startsWith('http://') || btn.url.startsWith('https://');

  const variantProps = btn.variant === 'primary'
    ? { variant: 'default' as const }
    : btn.variant === 'accent'
    ? { variant: 'outline' as const }
    : { variant: 'outline' as const };

  const accentClass = btn.variant === 'accent'
    ? 'border-orange-300 hover:bg-orange-50 dark:border-orange-700 dark:hover:bg-orange-900/20'
    : '';

  const primaryStyle = btn.variant === 'primary' ? { style: { background: 'linear-gradient(135deg, #ec4899, #8b5cf6)', border: 'none' } } : {};

  const ResolvedIcon: React.ComponentType<{ className?: string }> | null =
    btn.icon && BUTTON_ICON_COMPONENTS[btn.icon]
      ? BUTTON_ICON_COMPONENTS[btn.icon]
      : getDefaultIcon(btn.variant);

  const accentIconClass = btn.variant === 'accent' && !btn.icon
    ? 'text-orange-600 dark:text-orange-400'
    : '';

  // Mobile sizing:
  // - mobileShowLabel: compact pill (auto width) with icon + short label
  // - mobileIconOnly: square icon-only
  // - neither: normal full button
  const mobileClass = mobileIconOnly && !mobileShowLabel
    ? 'w-12 h-12 p-0 sm:w-auto sm:h-auto sm:px-4 sm:py-2'
    : mobileIconOnly && mobileShowLabel
    ? 'px-3 h-12 sm:px-4 sm:h-auto'
    : '';

  // What to render as label
  const labelNode = mobileIconOnly && !mobileShowLabel
    ? <span className="hidden sm:inline">{btn.label}</span>
    : btn.label;

  if (isExternal) {
    return (
      <Button size={size} {...variantProps} className={`rounded-full ${accentClass} ${mobileClass}`} {...primaryStyle} title={btn.label} asChild>
        <a href={btn.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5">
          {ResolvedIcon && <ResolvedIcon className={`h-5 w-5 sm:h-4 sm:w-4 flex-shrink-0 ${accentIconClass}`} />}
          {labelNode}
          <ExternalLink className="hidden sm:inline h-3 w-3 opacity-60" />
        </a>
      </Button>
    );
  }

  return (
    <Button size={size} {...variantProps} className={`rounded-full ${accentClass} ${mobileClass}`} {...primaryStyle} title={btn.label} asChild>
      <Link to={btn.url} className="flex items-center gap-1.5">
        {ResolvedIcon && <ResolvedIcon className={`h-5 w-5 sm:h-4 sm:w-4 flex-shrink-0 ${accentIconClass}`} />}
        {labelNode}
      </Link>
    </Button>
  );
}

function InterSectionButtons({ buttons }: { buttons: HomepageButton[] }) {
  if (!buttons || buttons.length === 0) return null;
  return (
    <div className="flex flex-wrap justify-center gap-3 mb-6 -mt-4">
      {buttons.map(btn => (
        <DynamicButton key={btn.id} btn={btn} size="default" />
      ))}
    </div>
  );
}

/** Pure image grid — no text, tiles link to their destination */
function PhotoGridTile({ tile }: { tile: GridTile }) {
  const [loaded, setLoaded] = useState(false);
  const [errored, setErrored] = useState(false);
  const thumbnail = useThumbnailUrl();

  return (
    <div className="relative aspect-square overflow-hidden bg-gray-200 dark:bg-gray-800 group">
      {/* Skeleton shown until the image has actually downloaded */}
      {!loaded && !errored && (
        <Skeleton className="absolute inset-0 h-full w-full" />
      )}
      <img
        src={thumbnail(tile.imageUrl, 400)}
        alt={tile.alt || ''}
        className={`w-full h-full object-cover transition-all duration-300 group-hover:scale-105 ${
          loaded ? 'opacity-100' : 'opacity-0'
        }`}
        loading="lazy"
        ref={(el) => {
          if (el?.complete && el.naturalWidth > 0 && !loaded) setLoaded(true);
        }}
        onLoad={() => setLoaded(true)}
        onError={() => setErrored(true)}
      />
      {/* subtle overlay on hover */}
      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors duration-200" />
      {/* Discount badge */}
      {tile.discount && tile.discount > 0 && (
        <div className="absolute top-1 right-1 z-10">
          <span className="text-[10px] font-bold bg-orange-500 text-white px-1.5 py-0.5 rounded-full shadow leading-none">
            -{tile.discount}%
          </span>
        </div>
      )}
    </div>
  );
}

function PhotoGrid({ tiles }: { tiles: GridTile[] }) {
  if (tiles.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4 text-muted-foreground">
        <LayoutGrid className="h-12 w-12 opacity-20" />
        <p className="text-sm">No tiles configured yet. Add some in Homepage Settings → Photo Grid.</p>
      </div>
    );
  }

  const sorted = [...tiles].sort((a, b) => a.order - b.order);

  return (
    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-1 sm:gap-1.5">
      {sorted.map(tile => {
        const isExternal = tile.linkUrl.startsWith('http://') || tile.linkUrl.startsWith('https://');
        const inner = <PhotoGridTile tile={tile} />;

        return isExternal ? (
          <a key={tile.id} href={tile.linkUrl} target="_blank" rel="noopener noreferrer" className="block rounded-sm overflow-hidden focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-purple-500">
            {inner}
          </a>
        ) : (
          <Link key={tile.id} to={tile.linkUrl} className="block rounded-sm overflow-hidden focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-purple-500">
            {inner}
          </Link>
        );
      })}
    </div>
  );
}

