import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet';
import { LoginArea } from '@/components/auth/LoginArea';
import { RelaySelector } from '@/components/RelaySelector';
import { Search } from '@/components/Search';
import { useIsAdmin } from '@/hooks/useIsAdmin';
import { useTheme } from '@/hooks/useTheme';
import { Menu, Moon, Sun, Shield, Search as SearchIcon, Video, Users, Palette, Sparkles, Blocks } from 'lucide-react';
import { cn } from '@/lib/utils';

// Get the base path from import.meta.env or default to '/'
const basePath = import.meta.env.BASE_URL || '/';

const navigationItems = [
  { name: 'News', href: '/blog', icon: `${basePath}News_button_1.svg`, highlight: false },
  { name: 'Artist', href: '/artist', icon: `${basePath}artist_button_1.svg`, highlight: false },
  { name: 'PopUp', href: '/popup', icon: `${basePath}PopUP_button_1.svg`, highlight: false },
  { name: 'Art', href: '/art', icon: `${basePath}Art_button_1.svg`, highlight: false },
  { name: 'Projects', href: '/projects', icon: `${basePath}projects_button_1.svg`, highlight: false },
  { name: 'Fundraising', href: '/fundraising', icon: `${basePath}fundrasing_button_1.svg`, highlight: false },
  { name: 'Shop', href: '/shop', icon: `${basePath}Shop_button_1.svg`, highlight: false },
];

export function Navigation() {
  const [isOpen, setIsOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const location = useLocation();
  const { theme, setTheme } = useTheme();
  // Check if current user is admin
  const isAdmin = useIsAdmin();

  const isActive = (href: string) => {
    if (href === '/') {
      return location.pathname === '/';
    }
    return location.pathname.startsWith(href);
  };

  const toggleTheme = () => {
    setTheme(theme === 'light' ? 'dark' : 'light');
  };

  return (
    <nav className="sticky top-0 z-50 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
      <div className="container mx-auto px-4">
        <div className="flex h-16 items-center justify-between">
          {/* Logo/Brand */}
          <Link
            to="/"
            className="flex items-center hover:opacity-80 transition-opacity"
          >
            <img 
              src={`${basePath}B-Funny_avatar_orange.svg`}
              alt="BitPopArt Logo" 
              className="h-10 w-10 flex-shrink-0"
            />
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-2">
            {navigationItems.map((item) => (
              <Link
                key={item.name}
                to={item.href}
                className={cn(
                  "flex items-center space-x-2 px-3 py-2 rounded-full text-sm font-medium transition-colors whitespace-nowrap",
                  item.highlight
                    ? isActive(item.href)
                      ? "bg-gradient-to-r from-orange-600 to-pink-600 text-white"
                      : "bg-gradient-to-r from-orange-500 to-pink-500 text-white hover:from-orange-600 hover:to-pink-600"
                    : isActive(item.href)
                      ? "bg-primary/10 text-primary"
                      : "text-muted-foreground hover:text-foreground hover:bg-accent"
                )}
              >
                {item.icon && <img src={item.icon} alt={item.name} className="h-5 w-5 flex-shrink-0" />}
                <span>{item.name}</span>
              </Link>
            ))}
          </div>

          {/* Desktop Actions */}
          <div className="hidden md:flex items-center space-x-4">
            <Link to="/community">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 px-3 gap-1.5 rounded-full font-medium text-sm"
                title="PopFans Community"
                style={{ color: '#f7931a' }}
              >
                <Users className="h-4 w-4" />
                <span>PopFans</span>
              </Button>
            </Link>
            <Link to="/wall">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 p-0 hover:opacity-80"
                title="Wall - Street Art Gallery"
              >
                <img 
                  src={`${basePath}spray_paint_icon.svg`} 
                  alt="Wall" 
                  className="h-5 w-5"
                />
              </Button>
            </Link>
            <Link to="/vlog">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 p-0 rounded-full text-white hover:opacity-90"
                style={{ backgroundColor: '#f7931a' }}
              >
                <Video className="h-4 w-4" />
              </Button>
            </Link>
            <Button
              variant="ghost"
              size="sm"
              onClick={toggleTheme}
              className="h-9 w-9 p-0"
            >
              {theme === 'light' ? (
                <Moon className="h-4 w-4" />
              ) : (
                <Sun className="h-4 w-4" />
              )}
            </Button>
            <Link to="/Block">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 px-3 gap-1.5 rounded-full font-medium text-sm bg-gradient-to-r from-yellow-100 to-orange-100 dark:from-yellow-900/30 dark:to-orange-900/30 hover:from-yellow-200 hover:to-orange-200 dark:hover:from-yellow-900/50 dark:hover:to-orange-900/50 text-orange-600 dark:text-orange-400"
              >
                <Blocks className="h-4 w-4" />
                <span>Block</span>
              </Button>
            </Link>
            <Link to="/NFT">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 px-3 gap-1.5 rounded-full font-medium text-sm bg-gradient-to-r from-orange-100 to-pink-100 dark:from-orange-900/30 dark:to-pink-900/30 hover:from-orange-200 hover:to-pink-200 dark:hover:from-orange-900/50 dark:hover:to-pink-900/50 text-orange-600 dark:text-orange-400"
              >
                <Sparkles className="h-4 w-4" />
                <span>NFT</span>
              </Button>
            </Link>
            {isAdmin && (
              <>
                <Button
                  asChild
                  variant="outline"
                  size="sm"
                  className="bg-gradient-to-r from-orange-50 to-orange-50 dark:from-orange-900/20 dark:to-orange-900/20 border-orange-200 dark:border-orange-800 hover:bg-gradient-to-r hover:from-orange-100 hover:to-orange-100 dark:hover:from-orange-900/30 dark:hover:to-orange-900/30"
                >
                  <Link to="/admin" className="flex items-center space-x-2">
                    <Shield className="h-4 w-4" style={{ color: '#e99840' }} />
                    <span className="font-medium" style={{ color: '#e99840' }}>Dashboard</span>
                  </Link>
                </Button>
                <Button
                  asChild
                  variant="outline"
                  size="sm"
                  className="border-orange-200 dark:border-orange-700 text-orange-600 dark:text-orange-400"
                >
                  <Link to="/nft-admin" className="flex items-center space-x-2">
                    <Sparkles className="h-4 w-4" />
                    <span className="font-medium">NFT Admin</span>
                  </Link>
                </Button>
              </>
            )}
            <LoginArea className="max-w-48" />
          </div>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center space-x-2">
            <Link to="/wall">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 p-0 hover:opacity-80"
                title="Wall - Street Art Gallery"
              >
                <img 
                  src={`${basePath}spray_paint_icon.svg`} 
                  alt="Wall" 
                  className="h-5 w-5"
                />
              </Button>
            </Link>
            <Link to="/vlog">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 p-0 rounded-full text-white hover:opacity-90"
                style={{ backgroundColor: '#f7931a' }}
              >
                <Video className="h-4 w-4" />
              </Button>
            </Link>
            <Sheet open={isOpen} onOpenChange={setIsOpen}>
              <SheetTrigger asChild>
                <Button variant="ghost" size="sm" className="h-9 w-9 p-0">
                  <Menu className="h-5 w-5" />
                </Button>
              </SheetTrigger>
              <SheetContent side="right" className="w-80">
                <div className="flex flex-col space-y-6 mt-6">
                  {/* Admin Dashboard Button (Mobile) */}
            <Link to="/NFT">
              <Button
                variant="ghost"
                size="sm"
                className="h-9 px-3 gap-1.5 rounded-full font-medium text-sm bg-gradient-to-r from-orange-100 to-pink-100 dark:from-orange-900/30 dark:to-pink-900/30 hover:from-orange-200 hover:to-pink-200 dark:hover:from-orange-900/50 dark:hover:to-pink-900/50 text-orange-600 dark:text-orange-400"
              >
                <Sparkles className="h-4 w-4" />
                <span>NFT</span>
              </Button>
            </Link>
            {isAdmin && (
                    <div className="px-4 space-y-2">
                      <Button
                        asChild
                        className="w-full text-white"
                        style={{ background: '#e99840' }}
                        onClick={() => setIsOpen(false)}
                      >
                        <Link to="/admin" className="flex items-center justify-center space-x-2">
                          <Shield className="h-5 w-5" />
                          <span className="font-medium">Admin Dashboard</span>
                        </Link>
                      </Button>
                      <Button
                        asChild
                        variant="outline"
                        className="w-full border-orange-300 dark:border-orange-700"
                        onClick={() => setIsOpen(false)}
                      >
                        <Link to="/nft-admin" className="flex items-center justify-center space-x-2">
                          <Sparkles className="h-5 w-5 text-orange-500" />
                          <span className="font-medium">NFT Admin</span>
                        </Link>
                      </Button>
                    </div>
                  )}

                  {/* Mobile Navigation Links */}
                  <div className="space-y-2">
                    {navigationItems.map((item) => (
                      <Link
                        key={item.name}
                        to={item.href}
                        onClick={() => setIsOpen(false)}
                        className={cn(
                          "flex items-center space-x-3 px-4 py-3 rounded-full text-base font-medium transition-colors",
                          item.highlight
                            ? isActive(item.href)
                              ? "bg-gradient-to-r from-orange-600 to-pink-600 text-white font-bold"
                              : "bg-gradient-to-r from-orange-500 to-pink-500 text-white font-bold"
                            : isActive(item.href)
                              ? "bg-primary/10 text-primary"
                              : "text-muted-foreground hover:text-foreground hover:bg-accent"
                        )}
                      >
                        {item.icon
                          ? <img src={item.icon} alt={item.name} className="h-6 w-6 flex-shrink-0" />
                          : <Palette className="h-6 w-6 flex-shrink-0" />
                        }
                        <span>{item.name}</span>
                      </Link>
                    ))}
                    {/* Community / PopFans */}
                    <Link
                      to="/community"
                      onClick={() => setIsOpen(false)}
                      className={cn(
                        "flex items-center space-x-3 px-4 py-3 rounded-full text-base font-medium transition-colors",
                        isActive('/community')
                          ? "bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400"
                          : "text-muted-foreground hover:text-foreground hover:bg-accent"
                      )}
                    >
                      <Users className="h-6 w-6 flex-shrink-0" style={{ color: '#f7931a' }} />
                      <span>PopFans</span>
                    </Link>
                    {/* Block Art */}
                    <Link
                      to="/Block"
                      onClick={() => setIsOpen(false)}
                      className={cn(
                        "flex items-center space-x-3 px-4 py-3 rounded-full text-base font-medium transition-colors",
                        isActive('/Block')
                          ? "bg-gradient-to-r from-yellow-100 to-orange-100 text-orange-600 dark:from-yellow-900/30 dark:to-orange-900/30 dark:text-orange-400"
                          : "text-muted-foreground hover:text-foreground hover:bg-accent"
                      )}
                    >
                      <Blocks className="h-6 w-6 flex-shrink-0 text-orange-500" />
                      <span>Block Art</span>
                    </Link>
                    {/* NFT */}
                    <Link
                      to="/NFT"
                      onClick={() => setIsOpen(false)}
                      className={cn(
                        "flex items-center space-x-3 px-4 py-3 rounded-full text-base font-medium transition-colors",
                        isActive('/NFT')
                          ? "bg-gradient-to-r from-orange-100 to-pink-100 text-orange-600 dark:from-orange-900/30 dark:to-pink-900/30 dark:text-orange-400"
                          : "text-muted-foreground hover:text-foreground hover:bg-accent"
                      )}
                    >
                      <Sparkles className="h-6 w-6 flex-shrink-0 text-orange-500" />
                      <span>NFT</span>
                    </Link>
                  </div>

                  <div className="border-t pt-6 space-y-4 px-4">
                    <Button
                      variant="outline"
                      className="w-full"
                      onClick={() => {
                        setIsOpen(false);
                        setSearchOpen(true);
                      }}
                    >
                      <SearchIcon className="mr-2 h-4 w-4" />
                      Search
                    </Button>
                    <RelaySelector className="w-full" />
                    <LoginArea className="w-full" />
                    <Button
                      variant="outline"
                      className="w-full"
                      onClick={toggleTheme}
                    >
                      {theme === 'light' ? (
                        <>
                          <Moon className="mr-2 h-4 w-4" />
                          Dark Mode
                        </>
                      ) : (
                        <>
                          <Sun className="mr-2 h-4 w-4" />
                          Light Mode
                        </>
                      )}
                    </Button>
                  </div>
                </div>
              </SheetContent>
            </Sheet>
          </div>
        </div>
      </div>

      {/* Search Dialog */}
      <Search open={searchOpen} onOpenChange={setSearchOpen} />
    </nav>
  );
}