import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { formatCurrency } from '@/hooks/usePayment';
import { useLivePrice } from '@/hooks/useLivePrice';
import { useFiatToSats } from '@/hooks/useFiatToSats';
import { useIsAdmin } from '@/hooks/useIsAdmin';
import { useThemeColors } from '@/hooks/useThemeColors';
import { useCart } from '@/hooks/useCart';
import { useToast } from '@/hooks/useToast';
import { SocialShareButtons } from '@/components/SocialShareButtons';
import { PaymentDialog } from './PaymentDialog';
import { ProductDetailsDialog } from './ProductDetailsDialog';
import { ImageGallery } from './ImageGallery';
import { PublishToMarketplaces } from './PublishToMarketplaces';
import {
  ShoppingCart,
  Package,
  Download,
  Eye,
  Truck,
  Zap,
  Plus,
  ExternalLink,
} from 'lucide-react';
import type { NostrEvent } from '@nostrify/nostrify';

interface ShippingRegion {
  id: string;
  name: string;
  countries: string;
  cost: number;
}

interface MarketplaceProduct {
  id: string;
  event?: NostrEvent; // NostrEvent - optional for sample data
  name: string;
  description: string;
  images: string[];
  currency: string;
  price: number;
  discount?: number; // Discount percentage (0-100)
  quantity?: number;
  category: string;
  type: 'physical' | 'digital';
  specs?: Array<[string, string]>;
  shipping?: ShippingRegion[];
  digital_files?: string[];
  product_url?: string; // URL for physical products
  contact_url?: string; // URL for contacting seller
  stall_id: string;
  created_at: string;
}

interface ProductCardProps {
  product: MarketplaceProduct;
  onViewDetails?: (product: MarketplaceProduct) => void;
}

export function ProductCard({ product, onViewDetails }: ProductCardProps) {
  const [paymentDialogOpen, setPaymentDialogOpen] = useState(false);
  const [detailsDialogOpen, setDetailsDialogOpen] = useState(false);
  const isAdmin = useIsAdmin();
  const navigate = useNavigate();
  const { getGradientStyle } = useThemeColors();
  const { addItem } = useCart();
  const { toast } = useToast();

  // Fetch live price from source URL if available
  const { data: livePrice, isLoading: priceLoading } = useLivePrice(
    product.contact_url || product.product_url,
    product.price,
    product.currency
  );

  const displayPrice = livePrice?.price ?? product.price;
  const displayCurrency = livePrice?.currency ?? product.currency;
  
  // Original (pre-discount) price in display currency — used for strikethrough
  const priceInUSD = displayPrice;

  // Calculate discounted price if discount is set
  const hasDiscount = product.discount && product.discount > 0;
  const discountedPriceUSD = hasDiscount ? priceInUSD * (1 - product.discount! / 100) : null;
  const finalDisplayPrice = discountedPriceUSD ?? priceInUSD;
  
  // Convert the actual display currency to sats (was hardcoded to 'USD' — now uses real currency)
  const { data: satsConversion } = useFiatToSats(finalDisplayPrice, displayCurrency);
  const displayPriceInSats = satsConversion ?? livePrice?.priceInSats;

  const isOutOfStock = product.quantity !== undefined && product.quantity <= 0;
  const hasShipping = product.shipping && product.shipping.length > 0;
  // External-only: product has a contact_url pointing to an external webshop.
  // These products can appear on Nostr marketplaces but are NOT sold through this site.
  const externalBuyUrl = product.contact_url && product.contact_url.trim() !== ''
    ? product.contact_url.trim()
    : undefined;

  const handleBuyNow = () => {
    if (externalBuyUrl) {
      window.open(externalBuyUrl, '_blank', 'noopener,noreferrer');
      return;
    }
    if (product.type === 'physical') {
      navigate(`/shop/${product.id}`);
    } else if (product.type === 'digital') {
      setPaymentDialogOpen(true);
    }
  };

  const handleViewDetails = () => {
    setDetailsDialogOpen(true);
    if (onViewDetails) {
      onViewDetails(product);
    }
  };

  const handleImageClick = () => {
    if (externalBuyUrl) {
      window.open(externalBuyUrl, '_blank', 'noopener,noreferrer');
      return;
    }
    if (product.type === 'physical') {
      navigate(`/shop/${product.id}`);
    } else if (product.type === 'digital') {
      setPaymentDialogOpen(true);
    }
  };

  const handleAddToCart = () => {
    addItem({
      id: product.id,
      name: product.name,
      price: finalDisplayPrice,
      currency: 'USD',
      discount: product.discount,
      images: product.images,
      type: product.type,
      category: product.category,
      shipping: product.shipping,
    });
    toast({
      title: 'Added to cart 🛒',
      description: `${product.name} added. Open cart to checkout.`,
    });
  };

  return (
    <>
      <Card className="group hover:shadow-lg transition-all duration-300 overflow-hidden bg-white/80 dark:bg-gray-800/80 backdrop-blur-sm">
        {/* Product Image */}
        <div className="relative">
          <ImageGallery
            images={product.images}
            productName={product.name}
            showThumbnails={product.images.length > 1}
            aspectRatio="square"
            onClick={handleImageClick}
            enableFullscreen={false}
          />

          {/* Product type badge */}
          <div className="absolute top-2 left-2 z-10 flex flex-col gap-1">
            <Badge variant={product.type === 'digital' ? 'default' : 'secondary'} className="text-xs">
              {product.type === 'digital' ? (
                <>
                  <Download className="w-3 h-3 mr-1" />
                  Digital
                </>
              ) : (
                <>
                  <Package className="w-3 h-3 mr-1" />
                  Physical
                </>
              )}
            </Badge>
            {externalBuyUrl && (
              <Badge className="text-xs bg-blue-500 text-white border-0 w-fit">
                <ExternalLink className="w-3 h-3 mr-1" />
                External Shop
              </Badge>
            )}
          </div>

          {/* Discount badge on image */}
          {hasDiscount && !isOutOfStock && (
            <div className="absolute top-2 right-2 z-10">
              <span className="text-xs font-bold bg-orange-500 text-white px-2 py-1 rounded-full shadow-md">
                -{product.discount}%
              </span>
            </div>
          )}

          {/* Stock status */}
          {isOutOfStock && (
            <div className="absolute top-2 right-2 z-10">
              <Badge variant="destructive" className="text-xs">
                Out of Stock
              </Badge>
            </div>
          )}
        </div>

        <CardHeader className="pb-2">
          <CardTitle className="text-lg font-semibold truncate group-hover:text-purple-600 transition-colors">
            {product.name}
          </CardTitle>
          <div className="flex items-center space-x-2 mt-1">
            <Badge variant="outline" className="text-xs">
              {product.category}
            </Badge>
            {product.quantity !== undefined && (
              <span className="text-xs text-muted-foreground">
                {product.quantity} available
              </span>
            )}
          </div>
        </CardHeader>

        <CardContent className="pt-0">
          <CardDescription className="text-sm line-clamp-2 mb-3">
            {product.description}
          </CardDescription>

          {/* Shipping info for physical products — calculated at checkout */}
          {product.type === 'physical' && (
            <div className="mb-3 flex items-center gap-1 text-xs text-muted-foreground">
              <Truck className="w-3 h-3 flex-shrink-0" />
              <span>Shipping calculated at checkout</span>
            </div>
          )}

          {/* Price */}
          <div className="mb-3">
            {priceLoading ? (
              <Skeleton className="h-6 w-20" />
            ) : (
              <>
                {hasDiscount && (
                  <div className="flex items-center space-x-2 mb-0.5">
                    <span className="line-through text-sm text-muted-foreground">
                      {formatCurrency(priceInUSD, displayCurrency)}
                    </span>
                    <span className="text-xs font-bold bg-orange-500 text-white px-1.5 py-0.5 rounded-full">
                      -{product.discount}%
                    </span>
                  </div>
                )}
                <div className="text-xl font-bold text-green-600 dark:text-green-400">
                  {formatCurrency(finalDisplayPrice, displayCurrency)}
                </div>
                {displayPriceInSats && (
                  <div className="flex items-center text-xs text-orange-600 dark:text-orange-400 mt-1">
                    <Zap className="w-3 h-3 mr-1" />
                    <span>{displayPriceInSats.toLocaleString()} sats</span>
                  </div>
                )}
                {externalBuyUrl && (
                  <p className="text-xs text-muted-foreground italic mt-1">
                    * Price shown at external shop
                  </p>
                )}
              </>
            )}
          </div>

          {/* Share Buttons - Admin Only */}
          {isAdmin && product.event && (
            <SocialShareButtons
              event={product.event}
              url={`/shop/${product.id}`}
              title={product.name}
              description={product.description}
              image={product.images[0]}
              contentType="product"
              className="mb-3"
            />
          )}

          {/* Publish to Nostr Marketplaces — Admin Only */}
          {isAdmin && (
            <div className="mb-3">
              <PublishToMarketplaces product={product} />
            </div>
          )}

          {/* Actions */}
          <div className="flex flex-col gap-2">
            {externalBuyUrl ? (
              /* External-only product — single button opening the external webshop */
              <Button
                size="sm"
                onClick={handleBuyNow}
                disabled={isOutOfStock}
                className="w-full text-white border-0 bg-blue-500 hover:bg-blue-600"
              >
                <ExternalLink className="w-4 h-4 mr-1.5" />
                {isOutOfStock ? 'Sold Out' : 'Buy at Shop'}
              </Button>
            ) : (
              <>
                <div className="flex gap-2">
                  {product.type === 'digital' && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleViewDetails}
                      className="flex items-center gap-1 flex-1"
                    >
                      <Eye className="w-4 h-4" />
                      <span>View</span>
                    </Button>
                  )}
                  <Button
                    size="sm"
                    onClick={handleBuyNow}
                    disabled={isOutOfStock}
                    className="text-white border-0 flex-1"
                    style={!isOutOfStock ? getGradientStyle('primary') : undefined}
                  >
                    <ShoppingCart className="w-4 h-4 mr-1" />
                    {isOutOfStock ? 'Sold Out' : (product.type === 'physical' ? 'View Product' : 'Buy Now')}
                  </Button>
                </div>
                {/* Add to Cart button — hidden for external products */}
                {!isOutOfStock && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleAddToCart}
                    className="w-full gap-1.5 border-orange-300 text-orange-700 hover:bg-orange-50 dark:border-orange-700 dark:text-orange-400 dark:hover:bg-orange-900/20"
                  >
                    <Plus className="w-3.5 h-3.5" />
                    Add to Cart
                  </Button>
                )}
              </>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Product Details Dialog */}
      <ProductDetailsDialog
        open={detailsDialogOpen}
        onOpenChange={setDetailsDialogOpen}
        product={product}
      />

      {/* Payment Dialog - Only for digital products */}
      {product.type === 'digital' && (
        <PaymentDialog
          open={paymentDialogOpen}
          onOpenChange={setPaymentDialogOpen}
          product={product}
        />
      )}
    </>
  );
}