import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useSeoMeta } from '@unhead/react';
import { useNostr } from '@nostrify/react';
import { useQuery } from '@tanstack/react-query';
import { useCurrentUser } from '@/hooks/useCurrentUser';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Separator } from '@/components/ui/separator';
import { Dialog, DialogContent } from '@/components/ui/dialog';
import { Calendar, Tag, ArrowLeft, ExternalLink, Image as ImageIcon, Share2 } from 'lucide-react';
import { format } from 'date-fns';
import type { NostrEvent } from '@nostrify/nostrify';
import ReactMarkdown from 'react-markdown';
import { ShareDialog } from '@/components/share/ShareDialog';
import { nip19 } from 'nostr-tools';

// Known blog author pubkey — used when resolving naddr references that embed it
const BLOG_AUTHOR_PUBKEY = '43baaf0c28e6cfb195b17ee083e19eb3a4afdfac54d9b6baf170270ed193e34c';

/**
 * Decode the :articleId route param, which can be either:
 *  - a plain d-tag string  (e.g. "blog-1782041934859")
 *  - an naddr1... identifier (NIP-19 addressable event reference)
 *
 * Returns { dTag, pubkey } to use in the Nostr filter.
 */
function decodeArticleParam(articleId: string): { dTag: string; pubkey: string } | null {
  if (!articleId) return null;

  if (articleId.startsWith('naddr1')) {
    try {
      const decoded = nip19.decode(articleId);
      if (decoded.type === 'naddr' && decoded.data.kind === 30023) {
        return {
          dTag: decoded.data.identifier,
          pubkey: decoded.data.pubkey,
        };
      }
    } catch {
      // fall through to plain d-tag handling
    }
  }

  // Plain d-tag — use the known blog author pubkey as a hint but don't require it
  return { dTag: articleId, pubkey: BLOG_AUTHOR_PUBKEY };
}

// Content block types
interface ContentBlock {
  id: string;
  type: 'markdown' | 'gallery';
  content: string;
  images: string[];
  externalUrl?: string;
}

export default function BlogPost() {
  const { articleId } = useParams<{ articleId: string }>();
  const navigate = useNavigate();
  const { nostr } = useNostr();
  const { user } = useCurrentUser();
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  // Decode the articleId — it may be a plain d-tag or an naddr1... identifier
  const decoded = articleId ? decodeArticleParam(articleId) : null;
  const dTag = decoded?.dTag ?? articleId ?? '';
  const authorPubkey = decoded?.pubkey ?? BLOG_AUTHOR_PUBKEY;

  // Fetch the specific blog post
  const { data: post, isLoading } = useQuery({
    queryKey: ['blog-post', dTag, authorPubkey],
    queryFn: async (c) => {
      if (!dTag) return null;
      
      const signal = AbortSignal.any([c.signal, AbortSignal.timeout(5000)]);
      
      // Always query by known author + d-tag for a precise, fast lookup.
      // Fall back to a broader search if the author-scoped query returns nothing.
      const events = await nostr.query(
        [{ kinds: [30023], authors: [authorPubkey], '#d': [dTag] }],
        { signal }
      );

      if (events.length > 0) return events[0];

      // Fallback: search without restricting author (covers edge cases)
      const fallback = await nostr.query(
        [{ kinds: [30023], '#d': [dTag], limit: 5 }],
        { signal }
      );
      return fallback[0] || null;
    },
    enabled: !!dTag,
    staleTime: 60_000,
  });

  const getContentBlocks = (): ContentBlock[] => {
    if (!post) return [];

    // NEW FORMAT: Check for blocks tag first
    const blocksTag = post.tags.find(t => t[0] === 'blocks')?.[1];
    if (blocksTag) {
      try {
        const parsed = JSON.parse(blocksTag);
        if (Array.isArray(parsed)) {
          return parsed;
        }
      } catch {
        // Invalid blocks tag, fall through
      }
    }

    // LEGACY FORMAT: Try parsing content as JSON
    try {
      const parsed = JSON.parse(post.content);
      if (parsed.blocks && Array.isArray(parsed.blocks)) {
        return parsed.blocks;
      }
    } catch {
      // Content is not JSON
    }

    // PLAIN MARKDOWN: Treat content as markdown
    const galleryImages = post.tags.filter(t => t[0] === 'gallery').map(t => t[1]);
    const blocks: ContentBlock[] = [{
      id: '1',
      type: 'markdown',
      content: post.content,
      images: []
    }];
    
    // Add gallery block if there are gallery images
    if (galleryImages.length > 0) {
      blocks.push({
        id: '2',
        type: 'gallery',
        content: '',
        images: galleryImages
      });
    }
    
    return blocks;
  };

  const getArticleTitle = (event: NostrEvent): string => {
    return event.tags.find(t => t[0] === 'title')?.[1] || 'Untitled';
  };

  const getArticleSummary = (event: NostrEvent): string => {
    return event.tags.find(t => t[0] === 'summary')?.[1] || '';
  };

  const getArticleImage = (event: NostrEvent): string | undefined => {
    return event.tags.find(t => t[0] === 'image')?.[1];
  };

  const getArticleTags = (event: NostrEvent): string[] => {
    return event.tags.filter(t => t[0] === 't' && t[1] !== 'blog').map(t => t[1]);
  };

  const getPublishedDate = (event: NostrEvent): Date => {
    const publishedAt = event.tags.find(t => t[0] === 'published_at')?.[1];
    return publishedAt ? new Date(parseInt(publishedAt) * 1000) : new Date(event.created_at * 1000);
  };

  const getSourceUrl = (event: NostrEvent): string | undefined => {
    return event.tags.find(t => t[0] === 'r')?.[1];
  };

  // Set SEO metadata
  const seoTitle = post ? getArticleTitle(post) : undefined;
  const seoSummary = post ? getArticleSummary(post) : undefined;
  const seoImage = post ? getArticleImage(post) : undefined;

  useSeoMeta({
    title: seoTitle ? `${seoTitle} - BitPopArt Blog` : 'Blog Post - BitPopArt',
    description: seoSummary || (post ? post.content.slice(0, 160) : 'Read this article on BitPopArt'),
    author: 'Johannes Oppewal (BitPopArt)',
    ogType: 'article',
    ogTitle: seoTitle ? `${seoTitle} - BitPopArt Blog` : 'Blog Post - BitPopArt',
    ogDescription: seoSummary || (post ? post.content.slice(0, 160) : 'Read this article on BitPopArt'),
    ogImage: seoImage || 'https://bitpopart.com/bitpopart-logo.png',
    ogImageAlt: seoTitle || 'BitPopArt Blog Article',
    ogSiteName: 'BitPopArt',
    ogUrl: `https://bitpopart.com/blog/${dTag}`,
    twitterCard: 'summary_large_image',
    twitterTitle: seoTitle ? `${seoTitle} - BitPopArt Blog` : 'Blog Post - BitPopArt',
    twitterDescription: seoSummary || (post ? post.content.slice(0, 160) : 'Read this article on BitPopArt'),
    twitterImage: seoImage || 'https://bitpopart.com/bitpopart-logo.png',
    twitterImageAlt: seoTitle || 'BitPopArt Blog Article',
    robots: 'index, follow, max-snippet:-1, max-image-preview:large',
  });

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-pink-50 via-purple-50 to-indigo-50 dark:from-gray-900 dark:via-purple-900/20 dark:to-indigo-900/20">
        <div className="container mx-auto px-4 py-12 max-w-4xl">
          <Skeleton className="h-12 w-32 mb-8" />
          <Skeleton className="h-64 w-full mb-8 rounded-lg" />
          <Skeleton className="h-12 w-3/4 mb-4" />
          <Skeleton className="h-6 w-1/2 mb-8" />
          <div className="space-y-4">
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-5/6" />
          </div>
        </div>
      </div>
    );
  }

  if (!post) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-pink-50 via-purple-50 to-indigo-50 dark:from-gray-900 dark:via-purple-900/20 dark:to-indigo-900/20">
        <div className="container mx-auto px-4 py-12 max-w-4xl">
          <Card>
            <CardContent className="py-12 text-center">
              <h2 className="text-2xl font-bold mb-4">Article Not Found</h2>
              <p className="text-muted-foreground mb-6">
                The article you're looking for doesn't exist or hasn't been published yet.
              </p>
              <Button onClick={() => navigate('/blog')}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Blog
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  const title = getArticleTitle(post);
  const summary = getArticleSummary(post);
  const image = getArticleImage(post);
  const postTags = getArticleTags(post);
  const publishedDate = getPublishedDate(post);
  const sourceUrl = getSourceUrl(post);
  const contentBlocks = getContentBlocks();

  return (
    <div className="min-h-screen bg-gradient-to-br from-pink-50 via-purple-50 to-indigo-50 dark:from-gray-900 dark:via-purple-900/20 dark:to-indigo-900/20">
      <div className="container mx-auto px-4 py-12 max-w-4xl">
        {/* Back Button */}
        <Button
          variant="ghost"
          onClick={() => navigate('/blog')}
          className="mb-8"
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Blog
        </Button>

        {/* Article */}
        <article>
          <Card className="overflow-hidden">
            {/* Featured Image */}
            {image && (
              <div className="w-full h-96 overflow-hidden">
                <img
                  src={image}
                  alt={title}
                  className="w-full h-full object-cover"
                />
              </div>
            )}

            <CardContent className="p-8 md:p-12">
              {/* Metadata */}
              <div className="flex flex-wrap items-center gap-4 mb-6 text-sm text-muted-foreground">
                <div className="flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  <time>{format(publishedDate, 'MMMM d, yyyy')}</time>
                </div>
                {sourceUrl && (
                  <a
                    href={sourceUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-2 hover:text-orange-600 transition-colors"
                  >
                    <ExternalLink className="h-4 w-4" />
                    View Original
                  </a>
                )}
              </div>

              {/* Title */}
              <h1 className="text-4xl md:text-5xl font-bold mb-6 gradient-header-text">
                {title}
              </h1>

              {/* Summary */}
              {summary && (
                <p className="text-xl text-muted-foreground mb-6 leading-relaxed">
                  {summary}
                </p>
              )}

              {/* Tags */}
              {postTags.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-8">
                  {postTags.map((tag) => (
                    <Badge key={tag} variant="secondary">
                      <Tag className="h-3 w-3 mr-1" />
                      {tag}
                    </Badge>
                  ))}
                </div>
              )}

              {/* Share Button */}
              <div className="flex justify-center mb-8">
                <ShareDialog
                  title={title}
                  description={summary}
                  url={`${window.location.origin}/blog/${dTag}`}
                  imageUrl={image}
                  category={postTags[0]}
                  contentType="blog"
                  eventRef={{
                    id: post.id,
                    kind: post.kind,
                    pubkey: post.pubkey,
                    dTag: dTag
                  }}
                >
                  <Button
                    variant="outline"
                    size="lg"
                    className="bg-gradient-to-r from-orange-50 to-pink-50 dark:from-orange-900/20 dark:to-pink-900/20 border-orange-200 dark:border-orange-800"
                  >
                    <Share2 className="h-4 w-4 mr-2" />
                    Share Article
                  </Button>
                </ShareDialog>
              </div>

              <Separator className="mb-8" />

              {/* Content Blocks */}
              <div className="space-y-8">
                {contentBlocks.map((block) => (
                  <div key={block.id}>
                    {/* Markdown Content Block */}
                    {block.type === 'markdown' && block.content.trim() && (
                      <div className="space-y-4">
                        <div className="prose prose-lg dark:prose-invert max-w-none break-words [&_h1]:text-4xl [&_h1]:font-bold [&_h1]:mb-6 [&_h1]:leading-tight [&_h2]:text-3xl [&_h2]:font-bold [&_h2]:mb-5 [&_h2]:mt-8 [&_h2]:leading-tight [&_h3]:text-2xl [&_h3]:font-semibold [&_h3]:mb-4 [&_h3]:mt-6 [&_p]:mb-4 [&_p]:leading-relaxed [&_ul]:mb-4 [&_ol]:mb-4 [&_li]:mb-2 [&_a]:text-purple-600 [&_a]:underline hover:[&_a]:text-purple-700 [&_blockquote]:border-l-4 [&_blockquote]:border-purple-500 [&_blockquote]:pl-4 [&_blockquote]:italic [&_code]:bg-gray-100 dark:[&_code]:bg-gray-800 [&_code]:px-1.5 [&_code]:py-0.5 [&_code]:rounded [&_code]:text-sm [&_pre]:bg-gray-100 dark:[&_pre]:bg-gray-800 [&_pre]:p-4 [&_pre]:rounded-lg [&_pre]:overflow-x-auto [&_img]:rounded-lg [&_img]:my-6">
                          <ReactMarkdown>{block.content}</ReactMarkdown>
                        </div>
                        {block.externalUrl && (
                          <div className="flex justify-center pt-4 border-t">
                            <Button
                              variant="outline"
                              size="sm"
                              asChild
                            >
                              <a href={block.externalUrl} target="_blank" rel="noopener noreferrer">
                                <ExternalLink className="h-4 w-4 mr-2" />
                                Related Link
                              </a>
                            </Button>
                          </div>
                        )}
                      </div>
                    )}

                    {/* Gallery Block */}
                    {block.type === 'gallery' && block.images.length > 0 && (
                      <div className="space-y-4">
                        {/* Single image: full width */}
                        {block.images.length === 1 ? (
                          <div
                            className="relative w-full overflow-hidden rounded-lg cursor-pointer group"
                            onClick={() => setSelectedImage(block.images[0])}
                          >
                            <img
                              src={block.images[0]}
                              alt="Image"
                              className="w-full h-auto object-contain group-hover:opacity-90 transition-opacity duration-300"
                            />
                          </div>
                        ) : (
                          /* Multiple images: grid layout */
                          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                            {block.images.map((imgUrl, index) => (
                              <div
                                key={index}
                                className="relative aspect-square overflow-hidden rounded-lg cursor-pointer group"
                                onClick={() => setSelectedImage(imgUrl)}
                              >
                                <img
                                  src={imgUrl}
                                  alt={`Image ${index + 1}`}
                                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
                                />
                                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center">
                                  <ImageIcon className="h-8 w-8 text-white" />
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                        {block.externalUrl && (
                          <div className="flex justify-center pt-4 border-t">
                            <Button
                              variant="outline"
                              size="sm"
                              asChild
                            >
                              <a href={block.externalUrl} target="_blank" rel="noopener noreferrer">
                                <ExternalLink className="h-4 w-4 mr-2" />
                                Related Link
                              </a>
                            </Button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <Separator className="mt-12 mb-8" />

              {/* Footer */}
              <div className="text-center">
                <Button onClick={() => navigate('/blog')} variant="outline" size="lg">
                  <ArrowLeft className="h-4 w-4 mr-2" />
                  Back to All Posts
                </Button>
              </div>
            </CardContent>
          </Card>
        </article>

        {/* Image Lightbox */}
        <Dialog open={!!selectedImage} onOpenChange={() => setSelectedImage(null)}>
          <DialogContent className="max-w-4xl p-0">
            {selectedImage && (
              <img
                src={selectedImage}
                alt="Gallery"
                className="w-full h-auto"
              />
            )}
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}
